function block(r,code,title,detail){r.code=code;r.title=title;r.summary=detail;r.wording='';r.tone='amber';r.pending.push(detail);r.actions.push('补齐该项事实后重新判断；当前不锁定免税或反向征税发票。');return finish(r);}
function finish(r){r.refs=[...new Set(r.refs)];r.pending=[...new Set(r.pending)];if(r.incoming.length)r.incoming.push('共同核对：法定主体、地址、发票日期/号码、货物或服务描述、数量、履行日期、净额，及依法需要的VAT号、税率税额或免税/反向征税说明。外国VAT不是德国Vorsteuer；错误计税先要求更正。');if(r.code!=='INCOMPLETE'&&!r.code.startsWith('ASK_'))r.status=r.tone==='teal'?'结构已判断 · 条件须落实':'分类已识别 · 留意待核实项';return r;}
function proof(s,r,kind){r.refs.push('evidence');if(s.evidence!=='YES')r.pending.push(`${kind}证明尚未核实齐备：收集出口/到货及账簿记录。如拟申请免税，还须满足相应实质条件；凭证齐备本身不代表具有免税资格。`);else r.known.push(entry('凭证状态（用户声明）','已选择凭证核实齐备；工具未读取或验证实际文件。',['evidence']));}
