function purchaseICS(s,r,d){const v=resolveVat(s,s.purchaseVat),ok=isEU(v)&&v!==s.origin&&s.purchaseValid==='YES'&&s.purchaseKind==='VAT';r.refs.push('ics','acquisition','eu','invoiceSpecial');r.known.push(entry('取得地',`实际跨成员国采购的取得地原则上在${label(d)}，由GmbH在当地申报。`,['acquisition']));r.incoming.push(ok?(s.origin==='DE'?'供应商可在条件满足后不收德国VAT；核对“Steuerfreie innergemeinschaftliche Lieferung”，双方VAT号及到货资料。':'供应商可按起运国规则审查欧盟内免税；核对“Exempt intra-Community supply / Art.138”或当地等效说明，不强求德国§6a。'):'购入端的他国有效VAT号条件尚未满足：不能要求供应商直接免税；先更正税号/告知记录，并协调计税、更正及到货国取得申报。');if(!ok)r.pending.push('GmbH向供应商使用的必须是起运国以外成员国授予的有效VAT号；Steuernummer不能代替欧盟内免税所需VAT号。');fallback(s,r,d);proof(s,r,'欧盟内运输');return ok;}
