 add('供应商使用起运国VAT号',a==='UNKNOWN'?'UNKNOWN':yes(a===s.origin));
 add('GmbH两端使用同一第三成员国VAT号',p==='UNKNOWN'||v==='UNKNOWN'?'UNKNOWN':yes(isEU(p)&&p===v&&p!==s.origin&&p!==d&&s.purchaseKind==='VAT'));
 add('GmbH所用号码有效且已告知',s.purchaseValid==='UNKNOWN'?'UNKNOWN':yes(s.purchaseValid==='YES'));
 add('最终客户使用到货国有效VAT号',c==='UNKNOWN'||s.customerValid==='UNKNOWN'?'UNKNOWN':yes(c===d&&s.customerValid==='YES'));
