 add('三角及纳税义务说明、双方VAT号、无单列税额',s.triangleInvoice==='YES'?'YES':s.triangleInvoice==='NO'?'NO':'UNKNOWN');
 add('正确汇总申报及三角标识已确认',s.zm==='YES'?'YES':s.zm==='NO'?'NO':'UNKNOWN');
 add('运输/到货及相关记录已核实',s.evidence==='YES'?'YES':'UNKNOWN');
