 if((['EU','BRANCH'].includes(s.recipient)&&(!isEU(d)||(s.recipient==='EU'&&d==='DE')))||(s.recipient==='THIRD'&&!THIRD[d]))return block(r,'ASK_DEST','确认实际目的国','欧盟分支可选择成员国；欧盟客户选择德国以外成员国，德国终端客户使用单独类别。');
 if(s.recipient==='BRANCH'&&s.identity!=='SAME')return block(r,'ASK_IDENTITY','分支与子公司分开判断','确认与GmbH为同一法律及VAT主体。独立子公司应选择“欧盟境内客户”，再检查B2B供货链。');
 if(s.recipient!=='BRANCH'&&!['B2B','B2C'].includes(s.buyer))return block(r,'ASK_BUYER','确认B2B或B2C','B2B表示企业为经营用途采购；没有VAT号不一定等于消费者，但会影响货物免税条件。');
