 if(!isEU(s.origin))return block(r,'ASK_ORIGIN','确认货物实际起运国','供应商总部国家不等于起运国；本版物流起点限德国/其他欧盟成员国。');
 if(s.supplierCountry!==s.origin)r.pending.push('供应商所在地与起运国不同：核实实际发货主体、当地VAT登记及涉入机构，不能仅按总部所在地计税。');
