 r.chain='构成（普通同物、直接运输的供货链）';r.known.push(entry('交易结构','供应商→GmbH→独立客户，两次真实供应、一次直接运输；B2C也不自动消除该供货链。',['chain']));
 if(s.origin===d){r.moving='境内运输；跨境归属不改变供应国';r.special='境内供应';noTriangle(r,'没有跨成员国运输');r.code=d==='DE'?'DOMESTIC_DE':'DOMESTIC_EU';r.title=`${label(d)}境内采购转售`;r.summary=d==='DE'?'两段普通供应均在德国，通常分别按适用德国VAT税率开票。':'两段普通供应均在同一外国成员国，按该国境内规则处理。';r.tone=d==='DE'?'teal':'amber';r.incoming.push(d==='DE'?'供应商通常开具含德国VAT发票；依法应纳的税额在§15条件满足时抵扣。':'核对当地VAT或有依据的当地反向征税，不在德国抵扣外国VAT。');r.outgoing.push(d==='DE'?'GmbH向B2B或B2C客户通常均按适用德国VAT计税；B2B身份本身不触发反向征税。':'GmbH需确认当地登记、当地税额或符合条件的当地反向征税；普通境内B2C货物销售不因已加入OSS即可纳入。');r.wording=d==='DE'?'Umsatzsteuer zum anwendbaren deutschen Steuersatz.':'Lokale Umsatzsteuer / lokale Steuerschuldnerschaft gesondert prüfen.';return finish(r);}
