 if(!isEU(s.origin))return block(r,'ASK_ORIGIN','确认完成后发货的实际起点','完成后再运输的工程货物仍可能是移动供应，提供本次合同货物起运国。');
 const d=incoming?recipient:destinationOf(s);if(!countries[d]||d==='UNKNOWN')return block(r,'ASK_WORK_DEST','确认本次工程货物交付国','采购端以GmbH实际受货国为准，销售端以终端交付国为准。');
 r.moving='被评估合同为完成后移动供货';r.special='货物规则；不推定三方链';r.known.push(entry('移动供货','完成后发运，或仅运输拆卸复装，仍须按货物移动供货规则判断；不自动变为安装地供应。',['place','install']));
 if(s.origin===d)return workTax(s,r,{incoming,buyer,provider,place:d,goods:true,werklieferung:s.foreignAsset==='YES',target});
 if(!isEU(d)){if(s.workTransport==='UNKNOWN')return block(r,'ASK_WORK_TRANSPORT','核实本工程货物谁负责出口运输','供方出口与受方自运的免税条件不同。');if(s.origin==='DE'&&s.workTransport==='RECIPIENT'&&((incoming&&s.purchaseEntity==='UNKNOWN')||(!incoming&&customerSeatOf(s)==='UNKNOWN')))return block(r,'ASK_FOREIGN_BUYER',"工程货物自运出口：先核实外国买方资格","德国起运且由买方负责出口时，须确认客户所在地；采购端还须确认由德国本部还是以自己名义签约的境外分支采购。仅有第三国收货地址不足以适用§6 Abs.1 Nr.2。");if(!incoming&&buyer==='B2C'&&s.workTransport==='RECIPIENT'&&s.personalLuggage!=='NO')return block(r,'ASK_LUGGAGE','工程货物的私人行李出口另查','消费者个人行李出口须核实§6 Abs.3a特别条件。');r.code='WORK_GOODS_EXPORT';r.title='完成后运输：审查本合同出口供应';r.summary='分类为货物供应后，再检查实际起运国出口条件。';target.push(s.origin==='DE'?'德国起运、供方自行出口时审查§6 Abs.1 Nr.1；受方自运时另核实外国买方条件。':'按外国起运国出口链和免税实施规则确认，不自动使用德国§6。');if(s.origin==='DE'&&s.workTransport==='RECIPIENT'&&(incoming?s.purchaseEntity==='HEAD':customerSeatOf(s)==='DE')){r.code='WORK_EXPORT_BUYER_TAX';r.title='本工程货物受方自运，但外国买方条件不足';target.push('按所选德国本部/客户事实，通常不能按外国买方自运出口免税；先核实德国计税，真正的外国承包方工程供货还须检查§13b。');r.refs.push('export');if(incoming)return workTax(s,r,{incoming,buyer,provider,place:'DE',goods:true,werklieferung:s.foreignAsset==='YES',target});r.wording='Deutsche Umsatzsteuer zum anwendbaren Steuersatz.';return finish(r);}if(incoming&&s.origin==='DE'&&s.workTransport==='RECIPIENT'&&s.purchaseEntity==='FOREIGN_BRANCH')r.pending.push('核实境外分支以自己名义签约、实际运输及§6外国买方资格；满足条件后供应商可审查出口免税，不直接认定必须列德国VAT。');r.refs.push('export');r.wording=s.origin==='DE'?'Steuerfreie Ausfuhrlieferung gemäß § 4 Nr. 1 Buchst. a i. V. m. § 6 UStG (Voraussetzungen prüfen).':'Export exemption under the applicable dispatch-state rules – to be confirmed.';proof(s,r,'出口');return finish(r);}
 if(incoming){r.code='WORK_GOODS_ACQUISITION';r.title='完成后跨境交付：GmbH欧盟内取得';r.summary='本合同是移动货物供应，通常不按德国境内外国工程供应直接套§13b。';purchaseICS(s,r,d);return finish(r);}
 if(buyer==='B2C')return distanceSale(s,r,d,'WORK');
 r.code='WORK_GOODS_ICS';r.title='完成后发运：审查免税欧盟内供应';r.summary='Werklieferung也可为移动货物供应；免税仍需客户有效VAT号、到货和汇总申报。';target.push('按实际起运国核对免税欧盟内供应；客户须使用他国有效VAT号，留存到货及正确汇总申报。');const cv=resolveVat(s,s.customerVat);const valid=isEU(cv)&&cv!==s.origin&&s.customerValid==='YES';if(!valid)r.pending.push('客户他国有效VAT号条件未落实，当前不能直接确认免税。');r.refs.push('ics');r.wording=s.origin==='DE'?'Steuerfreie innergemeinschaftliche Lieferung gemäß § 4 Nr. 1 Buchst. b i. V. m. § 6a UStG.':'Exempt intra-Community supply – dispatch-state conditions to be verified.';if(!valid){r.wording='';r.wordingNote="客户有效VAT号条件未满足，暂不提供免税发票措辞。先核实起运国计税及更正；其他免税条件仍需逐项落实。";}if(s.zm!=='YES')r.pending.push("核实本合同在起运国的汇总申报（Zusammenfassende Meldung）；尚未正确申报时，不把免税视为已经落实。");r.refs.push('zm','invoiceSpecial');proof(s,r,'欧盟内运输');return finish(r);
