function workTax(s,r,{incoming,buyer,provider,place,goods,werklieferung,target,serviceRecipient}){
 if(!r.code||r.code==='INCOMPLETE')r.code='WORK_LOCAL_GOODS';
 if(!r.title||r.title==='先确认交易事实')r.title=`${r.classification} · ${label(place)}供货`;
 if(place!=='DE'){
  if(!isEU(place)){target.push('不列德国VAT；第三国登记、销售税及可能反向征税由当地确认。');r.wording='Nicht im Inland steuerbare Leistung – Leistungsort im Drittland.';r.pending.push('核实第三国实际供应地、征税、登记及进口安排；本工具未核实各第三国国内法。');}
  else if(!goods&&buyer==='B2B'&&s.immovable==='NO'&&!incoming){if(s.serviceSupplierPresence==='UNKNOWN')return block(r,'ASK_FOREIGN_PRESENCE','核实GmbH在服务国是否有参与的固定机构','当地参与供货的机构可能改变Art.196反向征税适用，不能只看德国总部或所用号码。');if(s.serviceSupplierPresence==='INVOLVED'){r.code='WORK_SERVICE_EU_LOCAL';r.title='当地机构参与：按服务国税额另核实';target.push('GmbH在服务国有参与本合同的固定机构，不直接按跨境外国供方套Art.196；按当地计税及发票规则确认。');r.wording='Lokale Umsatzsteuer bei Beteiligung einer Betriebsstätte im Leistungsstaat prüfen.';return finish(r);}target.push('普通§3a Abs.2跨境B2B服务通常由客户在其成员国反向征税；留存企业身份及实际受领分支证明。','适用德国开票规则时，列双方VAT号，注明“Steuerschuldnerschaft des Leistungsempfängers”，最迟次月15日；按条件作ZM。');r.wording='Steuerschuldnerschaft des Leistungsempfängers (Reverse charge).';r.refs.push('zm');if(!isEU(resolveVat(s,s.customerVat))||!isEU(resolveVat(s,s.salesVat))){r.pending.push('本次服务发票所需双方VAT号尚未落实：补核号码，并以适当证据确认企业身份、当地RC资格及ZM，不能把缺号票视为已满足§14a。');r.wordingNote='双方号码、企业身份及RC条件待落实；当前仅显示条件性措辞，不能视为完整可用发票。';}if(s.customerValid!=='YES')r.pending.push('VAT号或企业身份未核实：B2B服务身份可用适当证据证明，但不要未经核实直接采用反向征税发票。');}
  else{target.push('按实际安装/作业/物业国的当地VAT及反向征税条件处理；不能把德国§13b直接套到外国。');r.wording='Lokale Umsatzsteuer / lokale Steuerschuldnerschaft im Leistungsstaat prüfen.';if(!goods&&buyer==='B2C'){target.push('如服务国不是GmbH设立地，可审查Union OSS的跨境B2C服务范围；若在服务国有实际设立，改当地申报。');r.refs.push('oss');}else if(goods&&(s.installation==='DEST'||s.immovable==='YES'))target.push('实质安装货物供应不适用普通远程销售；不能仅凭OSS参与取代安装地登记。');r.pending.push('当地供应地实施规则、登记、税率和可能反向征税需当地确认。');}
  return finish(r);
 }
 let rc=false,reason='';
 if(incoming&&provider!=='DE'){
  if(s.supplierDEPresence==='UNKNOWN')return block(r,'ASK_SUPPLIER_PRESENCE','核实外国供方是否有涉入的德国机构','外国VAT号、德国VAT号与实际设立不同；德国机构是否参与，会影响§13b。');
  if(s.supplierDEPresence==='NONE'&&(!goods||werklieferung)){rc=true;reason=goods?'§ 13b Abs. 2 Nr. 1、Abs. 5 UStG':(s.immovable==='NO'?'§ 13b Abs. 1 i. V. m. Abs. 5 UStG':'§ 13b Abs. 2 Nr. 1 i. V. m. Abs. 5 UStG');}
 }
 if(!rc&&s.construction==='YES'&&buyer==='B2B'){
  if(s.builder==='UNKNOWN')return block(r,'ASK_BUILDER','核实工程受方是否持续提供建筑服务','建筑工程的§13b反向征税须另查受方资格，不能因为合同名称叫工程就自动适用。');
  if(s.builder==='YES'){rc=true;reason='§ 13b Abs. 2 Nr. 4、Abs. 5 UStG';}
 }
 if(!rc&&s.construction==='UNKNOWN')return block(r,'ASK_CONSTRUCTION',"先确认是否属于建筑服务","是否属于建筑服务（Bauleistung）会改变纳税义务人。当前信息不足，先核实工程性质，再确定由供方计税还是受方反向征税。");
 if(rc){r.code=incoming?'WORK_DE_RC_IN':'WORK_DE_RC_OUT';r.title=`${r.classification} · 德国反向征税`;r.summary=`按所选外国供方/工程受方事实，适用${reason}，受方承担VAT。`;r.special='§13b Reverse charge';target.push(`不单列德国VAT；注明“Steuerschuldnerschaft des Leistungsempfängers”，核对${reason}及主体信息。`);if(incoming)target.push('GmbH自行申报德国§13b税额；符合§15 Abs.1 Nr.4等条件时另审查进项抵扣。');r.wording='Steuerschuldnerschaft des Leistungsempfängers gemäß § 13b UStG.';}
 else{r.code=incoming?'WORK_DE_TAX_IN':'WORK_DE_TAX_OUT';r.title=`${r.classification} · 通常列德国VAT`;r.summary='按所选事实尚未触发反向征税；普通安装供应与真正Werklieferung必须分开。';r.special='德国普通计税';target.push('通常按适用德国VAT税率开具发票；若存在其他§13b特别事项须另核实。');if(incoming&&provider!=='DE'&&goods&&!werklieferung)target.push('外国供方销售自有机器并在德国安装，不因“安装”就自动成为§13b Abs.2 Nr.1的Werklieferung；可能需供方德国登记及含税开票。');r.wording='Deutsche Umsatzsteuer zum anwendbaren Steuersatz.';}
 return finish(r);
}
